from pathlib import Path
import datetime, hashlib, json, math, os, sys, tomllib

ROOT = Path('/Users/masa/git/KagomeDMRG.jl')
DEST = ROOT / 'docs/research/data/p4_q5_matched_chi_csl_provenance_audit.json'
PATHS = {
 'fixed_q1': 'docs/research/data/p4_sector_refine_nn27_q1_chi256_validation.toml',
 'fixed_q3': 'docs/research/data/p4_campaign_nn27_q3_chi256_validation.toml',
 'parent_q5': 'docs/research/data/p4_sector_refine_nn27_q5_chi256_validation.toml',
 'chi256_q5': 'outputs/p4-q5-matched-chi256-8to9-20260920-r1/validation.toml',
 'chi512_q5': 'outputs/p4-q5-matched-chi512-8to9-20260920/validation.toml',
 'previous25610': 'docs/research/data/p4_q5_fixed_chi_8to10_validation.toml',
 'csl_old': 'outputs/p3-csl36-fixed-chi-8to10-20260920/validation.toml',
 'csl_new': 'outputs/p3-csl36-saved-moment-20260920/validation.toml',
}
files, discrepancies, sources = {}, [], {}
def check(value, description):
    if not value: discrepancies.append(description)
def digest(path): return hashlib.sha256(path.read_bytes()).hexdigest()
def file(path, expected=None):
    path = ROOT / path
    h = digest(path)
    files[str(path.relative_to(ROOT))] = {'sha256': h, 'bytes': path.stat().st_size}
    if expected is not None: check(h == expected, 'hash mismatch: '+str(path.relative_to(ROOT)))
    return h
def read(path):
    file(path)
    return tomllib.loads((ROOT / path).read_text())
def backend(d):
    identity = hashlib.sha256(json.dumps(d['code']['source_sha256'],sort_keys=True).encode()).hexdigest()
    if identity not in sources:
        base=d['backend_project']; source_map=d['code']['source_sha256']
        for f,h in source_map.items(): file(str(Path(base)/f),h)
        sources[identity]={'backend_project':base,'source_sha256':source_map,'files_rehashed':len(source_map)}
    return identity
def schmidt(rows, sz, zz=None):
    result=[]
    for s in rows:
        p=s['probabilities'];q=s['left_q'];b=s['bond']
        mean=math.fsum(pp*qq/2 for pp,qq in zip(p,q))
        variance=math.fsum(pp*(qq/2)**2 for pp,qq in zip(p,q))-mean**2
        errors={'probability_sum':abs(math.fsum(p)-1),'mean_from_saved':abs(mean-s['mean_left_sz']),
            'variance_from_saved':abs(variance-s['variance_left_sz']),
            'entropy_from_saved':abs(-math.fsum(pp*math.log(pp) for pp in p if pp>0)-s['entropy']),
            'mean_from_density':abs(mean-math.fsum(sz[:b]))}
        if zz is not None: errors['variance_from_correlations']=abs(variance-(math.fsum(zz[i][j] for i in range(b) for j in range(b))-math.fsum(sz[:b])**2))
        check(max(errors.values())<1e-9,'Schmidt mismatch at bond '+str(b))
        result.append({'bond':b,'errors':errors})
    return result
def checkpoint(cp,d,row,csl=False):
    m=read(str(Path(cp)/'metadata.toml')); c=read(str(Path(cp)/'checksums.toml'))
    for f,v in c['files'].items():
        file(str(Path(cp)/f),v['sha256']);check((ROOT/cp/f).stat().st_size==v['bytes'],'checkpoint byte count: '+cp+'/'+f)
    check(m['configuration']==d['configuration'],'checkpoint model: '+cp)
    check(m['provenance']['source_sha256']==d['code']['source_sha256'],'checkpoint backend: '+cp)
    check(m['runtime']=={k:v for k,v in d['runtime'].items() if k not in ['julia_threads','blas_threads']},'checkpoint runtime: '+cp)
    check(m['status']=='trial' and m['theta_path']==[0.0],'checkpoint status/path: '+cp)
    check(m['state']['energy']==row['energy'] and m['state']['sz']==row['sz_profile'],'checkpoint observables: '+cp)
    return m
def nn(role,d):
    rows=[r for r in d['batches'] if r.get('active_phase')=='completed']
    r=rows[-1];cp=r['checkpoint'];m=checkpoint(cp,d,r);ident=backend(d)
    out=Path(cp).parents[1]
    e=read(str(out/'execution.toml'))
    check(e['status']=='exited' and e['worker_exit_code']==0 and e['worker_exit_confirmed'],'NN execution: '+role)
    archive=out/'analysis-sources'
    for f,h in d['analysis_source_sha256'].items(): file(str(archive/f),h)
    config_candidates=[ROOT/archive/'config.toml',ROOT/archive/d['config_path']]
    config_archive=next((p for p in config_candidates if p.is_file()),config_candidates[0])
    if config_archive.is_file(): file(str(config_archive.relative_to(ROOT)),d['config_sha256'])
    else: file(d['config_path'],d['config_sha256'])
    if 'parent' in d:
        for f,h in d['parent']['checkpoint_sha256'].items(): file(f,h)
    z=r['correlations']['zz_real'];zi=r['correlations']['zz_imag'];p=r['correlations']['pm_real'];pi=r['correlations']['pm_imag'];sz=r['sz_profile'];N=d['N'];Q=d['Q']
    bonds=[b['Jz']*z[b['i']-1][b['j']-1]+b['Jxy']*p[b['i']-1][b['j']-1] for b in d['configuration']['bonds']]
    errors={'charge':abs(math.fsum(sz)-Q/2),'bond_sum':abs(math.fsum(r['bond_energy'])-r['energy']),
      'bond_from_correlations':max(abs(a-b) for a,b in zip(bonds,r['bond_energy'])),
      'zz_diagonal':max(abs(z[i][i]-.25) for i in range(N)),
      'pm_diagonal':max(abs(p[i][i]-(.5+sz[i])) for i in range(N)),
      'zz_imaginary':max(abs(x) for rr in zi for x in rr),
      'zz_symmetry':max(abs(z[i][j]-z[j][i]) for i in range(N) for j in range(N)),
      'pm_hermiticity':max(abs(complex(p[i][j]-p[j][i],pi[i][j]+pi[j][i])) for i in range(N) for j in range(N)),
      'fixed_charge_zz':max(abs(math.fsum(z[i])-Q/2*sz[i]) for i in range(N))}
    if 'HdaggerH_real' in r: errors['variance_arithmetic']=abs(r['HdaggerH_real']-r['energy']**2-r['variance'])
    check(max(errors.values())<1e-9,'NN observable arithmetic: '+role)
    return r,{'record':PATHS[role],'backend_identity':ident,'checkpoint':cp,
      'energy':r['energy'],'variance':r['variance'],'final_truncation':r['measured_truncation_errors'][-1],
      'errors':errors,'schmidt':schmidt(r['schmidt'],sz,z),'cumulative_sweeps':r['cumulative_sweeps'],
      'historical_backend_unchanged_flag':d.get('backend_unchanged'),
      'raw_second_moment_available':'HdaggerH_real' in r,
      'config_archive_present':config_archive.is_file(),
      'verified_config_path':str(config_archive.relative_to(ROOT)) if config_archive.is_file() else d['config_path']}
def profile_comparison(a,b,g):
    difference=lambda x,y:[bb-aa for aa,bb in zip(x,y)]
    dz=difference(a['sz_profile'],b['sz_profile']);db=difference(a['bond_energy'],b['bond_energy'])
    result={'energy_difference':b['energy']-a['energy'],'variance_difference':b['variance']-a['variance'],
      'max_sz_difference':max(map(abs,dz)),'max_bond_difference':max(map(abs,db)),
      'rms_sz_difference':math.sqrt(math.fsum(x*x for x in dz)/len(dz)),
      'rms_bond_difference':math.sqrt(math.fsum(x*x for x in db)/len(db))}
    site_lookup={(s['x'],s['y'],s['sublattice']):s['index']-1 for s in g['sites']}
    bond_lookup={tuple(sorted((bb['i']-1,bb['j']-1))):k for k,bb in enumerate(g['bonds'])}
    shifts=[]
    for shift in range(3):
        perm=[site_lookup[(s['x'],(s['y']+shift)%3,s['sublattice'])] for s in g['sites']]
        ds=[b['sz_profile'][perm[i]]-a['sz_profile'][i] for i in range(27)]
        de=[b['bond_energy'][bond_lookup[tuple(sorted((perm[bb['i']-1],perm[bb['j']-1])))]]-a['bond_energy'][k] for k,bb in enumerate(g['bonds'])]
        shifts.append({'shift':shift,'sz_rms':math.sqrt(math.fsum(x*x for x in ds)/27),'bond_rms':math.sqrt(math.fsum(x*x for x in de)/len(de))})
    result['circumference_shift_rms']=shifts
    return result
def main():
    d={role:read(p) for role,p in PATHS.items()}
    for role in ['chi256_q5','chi512_q5']: assert d[role]['status']=='completed_bounded_case_accuracy_separate',role+' unfinished'
    assert d['csl_new']['status']=='passed_saved_state_moment_audit','CSL unfinished or failed'
    audit={'schema_version':1,'recorded_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),
      'scope':'independent Python byte, metadata, and saved-number arithmetic audit; no analyzer helper imports; no new MPS contraction or ED',
      'new_MPS_contraction':False,'new_ED':False,'discrepancies':discrepancies,'nn':{}}
    rows={}
    for role in ['fixed_q1','fixed_q3','parent_q5','chi256_q5','chi512_q5','previous25610']:
        rows[role],audit['nn'][role]=nn(role,d[role])
    a,b=d['chi256_q5'],d['chi512_q5']; check(a['parent']==b['parent'],'common parent identity')
    check({k:v for k,v in a['config'].items() if k not in ['case_id','maxdim']}=={k:v for k,v in b['config'].items() if k not in ['case_id','maxdim']},'matched configs')
    check({k:v for k,v in a['solver'].items() if k!='maxdim'}=={k:v for k,v in b['solver'].items() if k!='maxdim'},'matched solver')
    g=a['configuration'];parent=rows['parent_q5'];comparisons={}
    for role in ['chi256_q5','chi512_q5']:
        r=rows[role];comparison=profile_comparison(parent,r,g)
        values={'energy_per_site':max(abs(r['energy']-parent['energy']),abs(r['energy']-r['sweep_energies'][-1]))/27,
          'sz_profile':comparison['max_sz_difference'],'bond_profile':comparison['max_bond_difference'],
          'variance_per_site':abs(r['variance'])/27,'truncation':r['measured_truncation_errors'][-1]}
        comparison['precision']={k:{'value':v,'threshold':d[role]['config']['stationarity'][k],'passed':v<=d[role]['config']['stationarity'][k]} for k,v in values.items()}
        comparison['final_two_sweep_difference']=None
        check(r['within_batch_sweep_change_measured'] is False and 'last_sweep_energy_change' not in r,'one-sweep missing semantics '+role)
        same=role=='chi256_q5';check(r['stationarity_evaluated']==same and r['same_chi_comparison']==same,'stationarity interpretation '+role)
        check(r['stationarity_passed']==(same and all(x['passed'] for x in comparison['precision'].values())),'stationarity decision '+role)
        comparisons['parent_to_'+role]=comparison
    comparisons['chi256_to_chi512']=profile_comparison(rows['chi256_q5'],rows['chi512_q5'],g)
    comparisons['chi256_9_to_previous256_10']=profile_comparison(rows['chi256_q5'],rows['previous25610'],g)
    comparisons['cumulative9_energy_agreement']=rows['chi256_q5']['energy']-rows['previous25610']['sweep_energies'][0]
    audit['comparisons']=comparisons
    e1,e3=rows['fixed_q1']['energy'],rows['fixed_q3']['energy'];audit['field_intervals']={};audit['sector_column_changes']={}
    for role in ['parent_q5','chi256_q5','chi512_q5','previous25610']:
        r=rows[role];lower=e3-e1;upper=r['energy']-e3
        audit['field_intervals'][role]={'h_lower':lower,'h_upper':upper,'width':upper-lower}
        columns=[math.fsum(r['sz_profile'][9*x+i]-rows['fixed_q3']['sz_profile'][9*x+i] for i in range(9)) for x in range(3)]
        audit['sector_column_changes'][role]={'Q3_to_Q5':columns,'sum_error':abs(math.fsum(columns)-1)}
        check(abs(math.fsum(columns)-1)<1e-10,'sector column sum '+role)
    old,new=d['csl_old'],d['csl_new'];r=old['preparation_batches'][0];m=new['measurement'];ident=backend(new)
    for p,h in new['input_sha256'].items(): file(p,h)
    newdir=Path(PATHS['csl_new']).parent
    for p,h in new['analysis_source_sha256'].items():file(str(newdir/'analysis-sources'/p),h)
    ex=read(str(newdir/'execution.toml'));check(ex['status']=='exited' and ex['worker_exit_code']==0 and ex['worker_exit_confirmed'],'CSL new execution')
    oe=read(str(Path(PATHS['csl_old']).parent/'execution.toml'))
    check(old['status']=='running' and oe['status']=='timed_out' and r['active_phase']=='variance','old CSL unfinished preserved')
    check(all(k not in r for k in ['raw_variance','integrity_passed','change_from_parent']),'old CSL missing fields preserved')
    meta=checkpoint(new['measurement']['checkpoint'],old,r,True)
    check(new['code']['source_sha256']==old['code']['source_sha256'] and new['runtime']==old['runtime'] and new['configuration']==old['configuration'],'CSL model/runtime/source match')
    check(meta['settings']['measure_variance'] is False and new['checkpoint_solver_variance_setting_changed'] is False,'saved variance setting preserved')
    check(new['original_worker_finalized'] is False and new['original_full_integrity_retroactively_claimed'] is False,'CSL historical completion semantics')
    floor=100*sys.float_info.epsilon*max(1,m['saved_energy']**2);variance=m['HdaggerH_real']-m['saved_energy']**2
    errors={'variance_arithmetic':abs(variance-m['raw_variance']),
      'remeasured_variance_arithmetic':abs(m['HdaggerH_real']-m['remeasured_energy_real']**2-m['variance_using_remeasured_energy']),
      'roundoff_scale':abs(floor-m['variance_roundoff_scale']),
      'energy_difference_arithmetic':abs(abs(complex(m['remeasured_energy_real']-m['saved_energy'],m['remeasured_energy_imag']))-m['energy_difference']),
      'density_difference_arithmetic':abs(max(abs(a-b) for a,b in zip(m['remeasured_sz_profile'],r['sz_profile']))-m['profile_max_difference']),
      'charge_error_arithmetic':abs(abs(math.fsum(m['remeasured_sz_profile']))-m['total_sz_error']),
      'old_bond_sum':abs(math.fsum(r['bond_energy_profile'])-r['energy'])}
    check(max(errors.values())<1e-9,'CSL arithmetic')
    fresh_checks={'finite_moment':math.isfinite(m['HdaggerH_real']) and math.isfinite(m['HdaggerH_imag']),
      'moment_imaginary':abs(m['HdaggerH_imag'])<=floor,'variance_nonnegative_within_roundoff':math.isfinite(variance) and variance>=-floor,
      'remeasured_energy_agreement':m['energy_difference']<=1e-10*max(1,abs(m['saved_energy'])),
      'norm_before':abs(m['norm_before']-1)<=1e-12,'norm_after':abs(m['norm_after']-1)<=1e-12,
      'state_overlap':m['overlap_change_error']<=1e-12,'state_tensors_unchanged':m['max_tensor_change']==0,
      'charge':m['total_sz_error']<=1e-12,'profile_agreement':m['profile_max_difference']<=1e-12 and all(math.isfinite(x) for x in m['remeasured_sz_profile'])}
    check(fresh_checks==m['checks'] and all(fresh_checks.values()) and m['passed'],'CSL diagnostic decisions')
    readiness={'variance':{'value':variance,'threshold':1e-3,'passed':variance<=1e-3},
      'truncation':{'value':r['measured_truncation_errors'][-1],'threshold':1e-5,'passed':r['measured_truncation_errors'][-1]<=1e-5},
      'sweep_energy_change':{'value':max(abs(r['sweep_energies'][-1]-r['sweep_energies'][-2]),abs(r['energy']-r['sweep_energies'][-1])),'threshold':1e-4}}
    readiness['sweep_energy_change']['passed']=readiness['sweep_energy_change']['value']<=1e-4
    audit['csl']={'backend_identity':ident,'checkpoint':m['checkpoint'],'old_worker_status':old['status'],'old_execution_status':oe['status'],
      'old_variance':None,'old_full_integrity':None,'old_parent_overlap':None,'new_variance':variance,'arithmetic_errors':errors,
      'schmidt_from_old_probabilities':schmidt(r['schmidt'],r['sz_profile']),'readiness_comparisons':readiness,
      'new_diagnostic_checks_recomputed':fresh_checks,'original_worker_finalized':False,'nonzero_pump_calibrated':False}
    comparison_path=ROOT/'docs/research/data/p4_q5_matched_chi_8to9_comparison.json'
    if comparison_path.exists():
        file(str(comparison_path.relative_to(ROOT))); comparison=json.loads(comparison_path.read_text());errs=[]
        for role,v in audit['field_intervals'].items():
            for k,x in v.items():errs.append(abs(x-comparison['field_intervals'][role][k]))
        audit['comparison_json_interval_max_error']=max(errs)
        check(max(errs)<1e-12,'comparison JSON intervals')
    audit['source_maps']=sources;audit['files']=files;audit['passed']=not discrepancies
    audit['limitations']=['Recomputed saved scalar and array arithmetic only; MPS claims rely on separately recorded Julia worker.',
      'Historical Q3 raw second moment and backend_unchanged flag are absent and remain unfilled; its original archived config was hash-verified.',
      'One-sweep chi response is not converged chi extrapolation; all finite-sector intervals remain nonrigorous trial comparisons.',
      'Missing historical CSL completion guards, integrity verdict and parent overlap are not reconstructed.']
    audit['reproduction']={'instruction':'Save python_source to a temporary .py file, adjust ROOT if needed, remove or rename only its generated audit output, then execute with Python 3.11+; no analyzer helper imports. Original numerical inputs must exist.',
       'python_source':Path(__file__).read_text()}
    assert not DEST.exists() or '--replace-own-audit' in sys.argv,'refuse to replace existing audit without explicit regeneration flag'
    encoded=json.dumps(audit,indent=2,sort_keys=True,allow_nan=False)+'\n'
    with DEST.open('w' if '--replace-own-audit' in sys.argv else 'x') as f:f.write(encoded)
    print(json.dumps({'path':str(DEST.relative_to(ROOT)),'passed':audit['passed'],'discrepancies':discrepancies,'field_intervals':audit['field_intervals'],'csl_readiness':readiness},indent=2))
    if discrepancies:sys.exit(1)
if __name__=='__main__':main()
